#include <stdio.h>

/* maiorDeIdade le a idade digitada e imprime "pode entrar" SO quando a
   idade e 18 ou mais. A leitura ja esta escrita.
   Hoje o printf roda sempre: falta o if para segurar essa linha. */
void maiorDeIdade(void) {
    int idade = 0;

    scanf("%d", &idade);

    printf("pode entrar\n");
}

