#include <stdio.h>

/* teste do desafio maior-de-idade — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos temporarios sao POR CENARIO: um cenario nunca le a entrada
   nem a captura do outro. Nunca ha fclose de stdin/stdout — so fflush —
   para o segundo freopen ficar legal (C11 7.21.4). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void maiorDeIdade(void);

SM_TEST(com_21_a_linha_sai) {
    /* o que a pessoa digita: 21 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "21\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    maiorDeIdade();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("com 21 a linha sai", linha, "pode entrar\n",
              "21 e maior ou igual a 18: a condicao vale 1 e o bloco roda");
    /* a saida TERMINA na primeira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e uma linha so: a linha de dentro do bloco do if");
    fclose(f);
}

SM_TEST(com_15_nada_sai) {
    /* outra idade digitada: agora a condicao e falsa */
    FILE *e = fopen("sm_entrada_2.tmp", "w");
    fprintf(e, "15\n");
    fclose(e);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
    maiorDeIdade();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("com 15 nada sai", linha, "(nada impresso)",
              "15 nao chega a 18: a condicao vale 0 e o bloco inteiro e saltado");
    fclose(f);
}

